mkdir -p /workspace/probes && cat > /tmp/gen.js <<'JSEOF'
const { execFileSync, spawnSync } = require('child_process');
const fs = require('fs');
const EXE = '/workspace/dataset/test13_executable';
const OUT = '/workspace/probes/validator-selection.jsonl';

const lines = [];
function runPair(a, b) {
  const r = spawnSync(EXE, ['--a', a, '--b', b], { encoding: 'utf8' });
  const rec = { a, b, out: r.stdout, exit: r.status };
  if (r.status !== 0 || r.stderr) rec.stderr = r.stderr;
  lines.push(JSON.stringify(rec));
}
function runArgv(argv, a, b) {
  const r = spawnSync(EXE, argv, { encoding: 'utf8' });
  const rec = { a: a === undefined ? null : a, b: b === undefined ? null : b,
                out: r.stdout, exit: r.status, argv };
  if (r.stderr) rec.stderr = r.stderr;
  lines.push(JSON.stringify(rec));
}

const S = (u) => JSON.stringify({ $schema: u });

// --- 1. $schema URI dispatch: every draft, http/https, with/without '#'
const uris = [
 'http://json-schema.org/draft-03/schema#','http://json-schema.org/draft-03/schema',
 'https://json-schema.org/draft-03/schema#','https://json-schema.org/draft-03/schema',
 'http://json-schema.org/draft-04/schema#','http://json-schema.org/draft-04/schema',
 'https://json-schema.org/draft-04/schema#','https://json-schema.org/draft-04/schema',
 'http://json-schema.org/draft-06/schema#','http://json-schema.org/draft-06/schema',
 'https://json-schema.org/draft-06/schema#','https://json-schema.org/draft-06/schema',
 'http://json-schema.org/draft-07/schema#','http://json-schema.org/draft-07/schema',
 'https://json-schema.org/draft-07/schema#','https://json-schema.org/draft-07/schema',
 'https://json-schema.org/draft/2019-09/schema','https://json-schema.org/draft/2019-09/schema#',
 'http://json-schema.org/draft/2019-09/schema','http://json-schema.org/draft/2019-09/schema#',
 'https://json-schema.org/draft/2020-12/schema','https://json-schema.org/draft/2020-12/schema#',
 'http://json-schema.org/draft/2020-12/schema','http://json-schema.org/draft/2020-12/schema#',
];
for (const u of uris) runPair('1', S(u));

// --- 2. URI normalization / case / fragments / whitespace
const weird = [
 'HTTP://json-schema.org/draft-07/schema#','HtTp://json-schema.org/draft-07/schema#',
 'http://JSON-SCHEMA.ORG/draft-07/schema#','http://Json-Schema.org/draft-07/schema#',
 'http://json-schema.org/DRAFT-07/schema#','http://json-schema.org/draft-07/Schema#',
 'http://json-schema.org/draft-07/schema##','http://json-schema.org/draft-07/schema#/definitions/foo',
 'http://json-schema.org/draft-07/schema#foo','http://json-schema.org/draft-07/schema/',
 'http://json-schema.org/draft-07/schema?','http://json-schema.org/draft-07/schema?x=1',
 '//json-schema.org/draft-07/schema#','json-schema.org/draft-07/schema#',
 'http://json-schema.org:80/draft-07/schema#','http://json-schema.org/draft-07/../draft-07/schema#',
 ' http://json-schema.org/draft-07/schema#','  http://json-schema.org/draft-07/schema',
 'http://json-schema.org/draft-07/schema# ','http://json-schema.org/draft-07/schema ',
 '\thttp://json-schema.org/draft-07/schema#','\nhttp://json-schema.org/draft-07/schema#',
 '\rhttp://json-schema.org/draft-07/schema#','http\t://json-schema.org/draft-07/schema#',
 'http://json-schema.org/draft-07/sch\nema#','https://json-schema.org/draft/2019-09/schema ',
 ' https://json-schema.org/draft/2020-12/schema','HTTPS://json-schema.org/draft/2020-12/schema',
];
for (const u of weird) runPair('1', S(u));

// --- 3. Unknown / alias / hyper / meta URIs
const unknown = [
 'http://json-schema.org/schema#','https://json-schema.org/schema#','http://json-schema.org/schema',
 'http://json-schema.org/draft-05/schema#','http://json-schema.org/draft-02/schema#',
 'http://json-schema.org/draft-01/schema#','http://json-schema.org/draft-00/schema#',
 'http://json-schema.org/hyper-schema#','http://json-schema.org/draft-07/hyper-schema#',
 'http://json-schema.org/draft-04/hyper-schema#','https://json-schema.org/draft/2019-09/hyper-schema',
 'https://json-schema.org/draft/2020-12/hyper-schema','https://json-schema.org/draft/2020-12/meta/core',
 'https://json-schema.org/draft/2020-12/meta/applicator','https://json-schema.org/draft/2019-09/meta/core',
 'https://json-schema.org/draft/2021-12/schema','urn:foo','foo','','   ','#',
];
for (const u of unknown) runPair('1', S(u));

// --- 4. Non-string $schema values
for (const v of ['1','0','-1','1.5','null','true','false','{}','[]','["http://json-schema.org/draft-07/schema#"]','{"a":1}','{"$ref":"x"}'])
  runPair('1', '{"$schema":' + v + '}');

// --- 5. Whole-schema types
for (const b of ['true','false','null','[]','[1,2]','["a"]','"hello"','""','1','0','1.5','-1'])
  runPair('1', b);
runPair('"x"', 'true');
runPair('"x"', 'false');
runPair('null', 'false');
runPair('[]', 'true');

// --- 6. Empty schema / $id only / nested $schema
runPair('1', '{}');
runPair('{"a":1}', '{}');
runPair('1', '{"$id":"http://example.com/x"}');
runPair('1', '{"id":"http://example.com/x"}');
runPair('1', '{"$id":"http://example.com/x","$schema":"http://json-schema.org/draft-04/schema#"}');
runPair('1', '{"$id":"http://example.com/x","$schema":"http://json-schema.org/draft-03/schema#"}');
runPair('1', '{"unknownKeyword":123}');
runPair('1', '{"$comment":"hi"}');
runPair('{"a":1}', '{"properties":{"a":{"$schema":"http://json-schema.org/draft-03/schema#","type":"string"}}}');
runPair('{"a":1}', '{"$schema":"http://json-schema.org/draft-07/schema#","properties":{"a":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"string"}}}');
runPair('{"a":1}', '{"$schema":"http://json-schema.org/draft-07/schema#","definitions":{"x":{"$schema":"http://json-schema.org/draft-03/schema#"}},"properties":{"a":{"$ref":"#/definitions/x"}}}');
runPair('1', '{"allOf":[{"$schema":"http://json-schema.org/draft-04/schema#"}]}');

// --- 7. Error counting plumbing
runPair('1', '{"type":"string","minimum":5,"maxLength":2}');
runPair('{"a":1,"b":2}', '{"properties":{"a":{"type":"string"},"b":{"type":"string"}}}');
runPair('{"a":1,"b":2,"c":3}', '{"properties":{"a":{"type":"string"},"b":{"type":"string"},"c":{"type":"string"}}}');
runPair('[1,2]', '{"items":{"type":"string"}}');
runPair('[1,2,3]', '{"items":{"type":"string"}}');
runPair('1', '{"anyOf":[{"type":"string"},{"type":"boolean"}]}');
runPair('1', '{"oneOf":[{"type":"string"},{"type":"boolean"}]}');
runPair('1', '{"allOf":[{"type":"string"},{"type":"boolean"}]}');
runPair('1', '{"not":{"type":"integer"}}');
runPair('{"a":{"b":1}}', '{"properties":{"a":{"properties":{"b":{"type":"string"}}}}}');
runPair('{"a":{"b":1,"c":2}}', '{"properties":{"a":{"properties":{"b":{"type":"string"},"c":{"type":"string"}}}}}');
runPair('1', '{"$ref":"#/definitions/x","definitions":{"x":{"type":"string"}}}');
runPair('1', '{"type":["string","boolean"]}');
runPair('1', '{"if":{"type":"integer"},"then":{"type":"string"}}');

// --- 8. Cross-draft semantics that depend on dispatch
const drafts = ['http://json-schema.org/draft-03/schema#','http://json-schema.org/draft-04/schema#',
 'http://json-schema.org/draft-06/schema#','http://json-schema.org/draft-07/schema#',
 'https://json-schema.org/draft/2019-09/schema','https://json-schema.org/draft/2020-12/schema'];
const bodies = [
  ['3', '"exclusiveMinimum":5'],
  ['3', '"minimum":5,"exclusiveMinimum":true'],
  ['[1,"a"]', '"items":[{"type":"integer"},{"type":"integer"}]'],
  ['[1,"a"]', '"prefixItems":[{"type":"integer"},{"type":"integer"}]'],
  ['5', '"$ref":"#/definitions/x","definitions":{"x":{"type":"string"}},"maximum":1'],
  ['{"a":1}', '"properties":{"a":{"type":"string"}},"required":["b"]'],
  ['{"a":1}', '"properties":{"a":{"type":"string","required":true}}'],
  ['1', '"const":2'],
  ['[1]', '"contains":{"type":"string"}'],
  ['{"a":1}', '"dependencies":{"a":["b"]}'],
  ['1', '"$defs":{"x":{"type":"string"}},"$ref":"#/$defs/x"'],
  ['1', '"definitions":{"x":{"type":"string"}},"$ref":"#/definitions/x"'],
  ['1', '"type":"any"'],
  ['1', '"type":"integer"'],
  ['1.0', '"type":"integer"'],
  ['{}', '"type":"object","properties":{}'],
];
for (const [inst, body] of bodies)
  for (const d of drafts)
    runPair(inst, '{"$schema":' + JSON.stringify(d) + ',' + body + '}');

// --- 9. Malformed JSON args
runPair('', '{}');
runPair('1', '');
runPair('{', '{}');
runPair('1', '{');
runPair('nan', '{}');
runPair('NaN', '{}');
runPair('Infinity', '{}');
runPair("'1'", '{}');
runPair('01', '{}');
runPair('1 ', '{}');
runPair(' 1', '{}');

// --- 10. CLI / argparse behavior
runArgv(['--a=1','--b={}'], '1', '{}');
runArgv(['--a=1','--b','{}'], '1', '{}');
runArgv(['--b','{}','--a','1'], '1', '{}');
runArgv(['--b={"type":"string"}','--a=1'], '1', '{"type":"string"}');
runArgv(['--a','1','--a','"x"','--b','{"type":"string"}'], '"x"', '{"type":"string"}');
runArgv(['--b','{"type":"string"}','--b','{"type":"integer"}','--a','1'], '1', '{"type":"integer"}');
runArgv(['--a','1']);
runArgv(['--b','{}']);
runArgv([]);
runArgv(['--c','1','--a','1','--b','{}']);
runArgv(['--a','1','--b','{}','--c','1']);
runArgv(['5','--a','1','--b','{}']);
runArgv(['--a','1','--b','{}','extra']);
runArgv(['-h']);
runArgv(['--help']);
runArgv(['-h','--a','1','--b','{}']);
runArgv(['--a','1','--b','{}','-h']);
runArgv(['-a','1','-b','{}']);
runArgv(['-a','1','--b','{}']);
runArgv(['--a','-5','--b','{}'], '-5', '{}');
runArgv(['--a','-5','--b','{"type":"string"}'], '-5', '{"type":"string"}');
runArgv(['--a=-5','--b','{}'], '-5', '{}');
runArgv(['--a','--b','{}']);
runArgv(['--a','1','--b']);
runArgv(['--','--a','1','--b','{}']);
runArgv(['--a','1','--b','{}','--']);
runArgv(['--a','1','--','--b','{}']);
runArgv(['--a=','--b=']);
runArgv(['--a','','--b','{}']);
runArgv(['--A','1','--B','{}']);
runArgv(['--a','1','--b','{}','--a','2'], '2', '{}');
runArgv(['--help','--c']);
runArgv(['--a','-x','--b','{}']);
runArgv(['--a','--1','--b','{}']);

fs.writeFileSync(OUT, lines.join('\n') + '\n');
console.log('wrote', lines.length, 'vectors');
