const { spawnSync } = require('child_process');
const fs = require('fs');
const EXE = '/workspace/dataset/test13_executable';
const OUT = '/workspace/probes/validator-selection.jsonl';
const lines = [];
function runPair(a,b){const r=spawnSync(EXE,['--a',a,'--b',b],{encoding:'utf8'});const rec={a,b,out:r.stdout,exit:r.status};if(r.status!==0||r.stderr)rec.stderr=r.stderr;lines.push(JSON.stringify(rec));}
function runArgv(argv,a,b){const r=spawnSync(EXE,argv,{encoding:'utf8'});const rec={a:a===undefined?null:a,b:b===undefined?null:b,out:r.stdout,exit:r.status,argv};if(r.stderr)rec.stderr=r.stderr;lines.push(JSON.stringify(rec));}

// argparse abbreviation of --help
runArgv(['--h']); runArgv(['--he']); runArgv(['--hel']); runArgv(['--hell']);
runArgv(['--a','1','--b','{}','--h']);
runArgv(['-x']); runArgv(['-']); runArgv(['--']);
runArgv(['--a=--b','--b={}'], '--b', '{}');
runArgv(['--a=1','--b=false'], '1', 'false');
runArgv(['--a','1','--b','{}','--b','false'], '1', 'false');
runArgv(['--a','{"a":1}','--b','{"required":["b"]}'], '{"a":1}', '{"required":["b"]}');
runArgv(['--b','{}','--a','1','--b','false'], '1', 'false');

// more $schema edge cases
for (const u of ['http://json-schema.org/draft-07/schema?',
                 'http://json-schema.org/draft-07/schema#?',
                 'http://json-schema.org/draft-07/schema',
                 'HTTP://JSON-SCHEMA.ORG/DRAFT-07/SCHEMA#',
                 'http:/json-schema.org/draft-07/schema#',
                 'http:///json-schema.org/draft-07/schema#',
                 'http://json-schema.org//draft-07/schema#',
                 'https://json-schema.org/draft/2019-09/schema##',
                 'https://json-schema.org/draft/2020-12/schema##',
                 'https://json-schema.org/draft/2020-12/schema?',
                 'HTTPS://JSON-SCHEMA.ORG/draft/2020-12/schema'])
  runPair('1', JSON.stringify({$schema:u}));

// $schema combined with an actually failing instance, per draft, to see class+count together
for (const u of ['http://json-schema.org/draft-03/schema#','http://json-schema.org/draft-04/schema#',
                 'http://json-schema.org/draft-06/schema#','http://json-schema.org/draft-07/schema#',
                 'https://json-schema.org/draft/2019-09/schema','https://json-schema.org/draft/2020-12/schema',
                 'bogus'])
  runPair('{"a":1,"b":2}', JSON.stringify({$schema:u, properties:{a:{type:'string'},b:{type:'string'}}, type:'array'}));

// schema true/false nested + boolean root with instances of each type
for (const a of ['1','"s"','[1]','{"k":1}','null','true','1.5']) { runPair(a,'true'); runPair(a,'false'); }

// $schema inside items/additionalProperties
runPair('[1]','{"items":{"$schema":"http://json-schema.org/draft-03/schema#","type":"string"}}');
runPair('{"a":1}','{"additionalProperties":{"$schema":"http://json-schema.org/draft-04/schema#","type":"string"}}');

fs.appendFileSync(OUT, lines.join('\n') + '\n');
console.log('appended', lines.length);
